-- Mycelix high-assurance verifier challenge registry.
-- Raw challenges are generated by the verifier using an OS CSPRNG and are
-- never persisted. Store only a domain-separated SHA-256 digest of each
-- 32-byte random challenge. Digest uniqueness prevents accidental re-issue.

CREATE SCHEMA IF NOT EXISTS identity_security;

CREATE TABLE IF NOT EXISTS identity_security.verifier_challenges (
    challenge_digest BYTEA PRIMARY KEY,
    verifier_id TEXT NOT NULL CHECK (length(verifier_id) BETWEEN 1 AND 512),
    audience TEXT NOT NULL CHECK (length(audience) BETWEEN 1 AND 2048),
    transaction_id UUID NOT NULL,
    request_digest BYTEA NOT NULL CHECK (octet_length(request_digest) = 32),
    holder_binding_digest BYTEA NOT NULL CHECK (octet_length(holder_binding_digest) = 32),
    issued_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ,
    CONSTRAINT verifier_challenge_digest_length
        CHECK (octet_length(challenge_digest) = 32),
    CONSTRAINT verifier_challenge_expiry_after_issue
        CHECK (expires_at > issued_at),
    CONSTRAINT verifier_challenge_consumed_after_issue
        CHECK (consumed_at IS NULL OR consumed_at >= issued_at)
);

CREATE INDEX IF NOT EXISTS verifier_challenges_unconsumed_expiry_idx
    ON identity_security.verifier_challenges (expires_at)
    WHERE consumed_at IS NULL;

-- Register exactly once. A duplicate digest is a hard failure; the caller
-- must generate a fresh random challenge. No raw challenge enters the DB.
CREATE OR REPLACE FUNCTION identity_security.register_verifier_challenge(
    p_challenge_digest BYTEA,
    p_verifier_id TEXT,
    p_audience TEXT,
    p_transaction_id UUID,
    p_request_digest BYTEA,
    p_holder_binding_digest BYTEA,
    p_expires_at TIMESTAMPTZ
) RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, identity_security
AS $$
DECLARE
    inserted_rows INTEGER;
    db_now TIMESTAMPTZ := clock_timestamp();
BEGIN
    IF p_challenge_digest IS NULL OR octet_length(p_challenge_digest) <> 32
       OR p_request_digest IS NULL OR octet_length(p_request_digest) <> 32
       OR p_holder_binding_digest IS NULL OR octet_length(p_holder_binding_digest) <> 32
       OR p_verifier_id IS NULL OR length(p_verifier_id) NOT BETWEEN 1 AND 512
       OR p_audience IS NULL OR length(p_audience) NOT BETWEEN 1 AND 2048
       OR p_transaction_id IS NULL
       OR p_expires_at IS NULL OR p_expires_at <= db_now THEN
        RETURN FALSE;
    END IF;

    INSERT INTO identity_security.verifier_challenges (
        challenge_digest, verifier_id, audience, transaction_id,
        request_digest, holder_binding_digest, issued_at, expires_at
    ) VALUES (
        p_challenge_digest, p_verifier_id, p_audience, p_transaction_id,
        p_request_digest, p_holder_binding_digest, db_now, p_expires_at
    )
    ON CONFLICT (challenge_digest) DO NOTHING;

    GET DIAGNOSTICS inserted_rows = ROW_COUNT;
    RETURN inserted_rows = 1;
END;
$$;

-- Atomic consume-once operation. The UPDATE is the serialization point.
-- Concurrent callers for one digest contend on this row; after the winner
-- commits, later callers re-check consumed_at IS NULL and update zero rows.
CREATE OR REPLACE FUNCTION identity_security.consume_verifier_challenge(
    p_challenge_digest BYTEA,
    p_verifier_id TEXT,
    p_audience TEXT,
    p_transaction_id UUID,
    p_request_digest BYTEA,
    p_holder_binding_digest BYTEA
) RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, identity_security
AS $$
DECLARE
    updated_rows INTEGER;
BEGIN
    IF p_challenge_digest IS NULL OR octet_length(p_challenge_digest) <> 32
       OR p_request_digest IS NULL OR octet_length(p_request_digest) <> 32
       OR p_holder_binding_digest IS NULL OR octet_length(p_holder_binding_digest) <> 32
       OR p_verifier_id IS NULL OR p_audience IS NULL OR p_transaction_id IS NULL THEN
        RETURN FALSE;
    END IF;

    UPDATE identity_security.verifier_challenges
       SET consumed_at = clock_timestamp()
     WHERE challenge_digest = p_challenge_digest
       AND verifier_id = p_verifier_id
       AND audience = p_audience
       AND transaction_id = p_transaction_id
       AND request_digest = p_request_digest
       AND holder_binding_digest = p_holder_binding_digest
       AND consumed_at IS NULL
       AND expires_at > clock_timestamp();

    GET DIAGNOSTICS updated_rows = ROW_COUNT;
    RETURN updated_rows = 1;
END;
$$;

-- The service role must receive EXECUTE on these two functions through a
-- deployment-specific role grant. It must not receive direct UPDATE/DELETE
-- access to the table. Keep digest tombstones to prevent accidental reuse.
REVOKE ALL ON identity_security.verifier_challenges FROM PUBLIC;
REVOKE ALL ON FUNCTION identity_security.register_verifier_challenge(
    BYTEA, TEXT, TEXT, UUID, BYTEA, BYTEA, TIMESTAMPTZ
) FROM PUBLIC;
REVOKE ALL ON FUNCTION identity_security.consume_verifier_challenge(
    BYTEA, TEXT, TEXT, UUID, BYTEA, BYTEA
) FROM PUBLIC;
